; BOOTUP.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; TITLE: start-up and the scrolling title picture (1209-14C9).
;
; Overview: BOOTUP.BIN is the menu program, chain-loaded by ULTIMA.COM. StartUp loads
; the files and runs TitleLoop: the DEMO.ULT landscape animated by the MOVES.ULT script in a
; frame under the intro's "Exodus" title, until a key brings up the main menu (RunMainMenu):
; Return to the View, Organize a Party (RunOrganizeMenu, ORGANIZE.ASM) or Journey Onward
; (JourneyOnward: chain-load EXODUS.BIN). Also here: DrawMenuFrame and ClearMenu
; (ClearMenu), used by every menu. The menus are drawn in the frame's inside, text rows
; 11-22; "Press <Space>" (WaitSpace, CREATE.ASM) goes on its bottom line, row 23.
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN StackArea:BYTE
EXTRN TileGfx:BYTE
EXTRN CharGfx:BYTE
EXTRN SwapCursor:NEAR
EXTRN FillCell:NEAR
EXTRN DrawTileBlock:NEAR
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN AskChoice:NEAR
EXTRN LoadFile:NEAR
EXTRN PrintAt:NEAR
EXTRN PspFcb:BYTE
EXTRN FcbCurBlock:BYTE
EXTRN FcbRecSize:BYTE
EXTRN FcbFileSize:BYTE
EXTRN FcbCurRec:BYTE
EXTRN ChainInt21:BYTE
EXTRN ChainJmp:BYTE
EXTRN ChainJmpAddr:BYTE
EXTRN DiskCheckResult:BYTE
EXTRN PartyBuf:BYTE
EXTRN Location:BYTE
EXTRN PartySize:BYTE
EXTRN Roster:BYTE
EXTRN DemoTiles:BYTE
EXTRN MovesCells:BYTE
EXTRN MovesValues:BYTE
EXTRN DemoStep:BYTE
EXTRN FileExodusBin:BYTE
EXTRN FileShapesUlt:BYTE
EXTRN FileRosterUlt:BYTE
EXTRN FilePartyUlt:BYTE
EXTRN FileDemoUlt:BYTE
EXTRN FileMovesUlt:BYTE
EXTRN FileCharsetUlt:BYTE
EXTRN MsgUltimaIII:BYTE
EXTRN MsgPressSpace:BYTE
EXTRN MsgCopyright:BYTE
EXTRN MsgLordBritish:BYTE
EXTRN MsgFromDepths:BYTE
EXTRN MsgVengeance:BYTE
EXTRN MsgOptionSpace:BYTE
EXTRN MsgMenuReturn:BYTE
EXTRN MsgMenuOrganize:BYTE
EXTRN MsgMenuJourney:BYTE
EXTRN MainMenuKeys:BYTE
EXTRN MainMenu:BYTE
EXTRN MsgNoActivePlayers:BYTE
EXTRN MsgStrangeDisk:BYTE
EXTRN MsgNoParty:BYTE
EXTRN CritErrRetry:NEAR
EXTRN RunOrganizeMenu:NEAR
EXTRN WaitSpace:NEAR
EXTRN AnimateDemo:NEAR
EXTRN AnyAlive:NEAR
EXTRN AskScenarioDisk:NEAR
PUBLIC StartUp
PUBLIC DrawMenuFrame
PUBLIC ClearMenu
;------------------------------------------------------------------------------
; BreakHandler: the int 23h (Ctrl-Break) handler: do nothing. CritErrRetry (CritErrRetry, the int
; 24h handler, the last bytes of BDATA) sets AL = 1 (retry) and runs into this iret.
;------------------------------------------------------------------------------
BreakHandler:	iret	;@1209
;------------------------------------------------------------------------------
; StartUp: the program's entry (jmp at 0100), reached by ULTIMA.COM's chain load
; with the intro's screen still showing (mode 4; the "Exodus" title stays at the top). Loads
; CHARSET, SHAPES, DEMO, MOVES, ROSTER and PARTY.ULT, draws the frame of the menu area with
; the DEMO.ULT landscape in it, then runs TitleLoop. Never returns: the program ends with
; the chain load of EXODUS.BIN (JourneyOnward).
;------------------------------------------------------------------------------
StartUp:	lea sp, StackArea	;@120A
	add sp, 100h	;@120E
	mov ax, 0	;@1212
	push es	;@1215
	mov es, ax	;@1216
	mov ax, cs	;@1218
	mov word ptr es:[8Ch], offset BreakHandler	; vector 23h (0000:008C): Ctrl-Break	;@121A
	mov word ptr es:[8Eh], ax	;@1221
	mov word ptr es:[90h], offset CritErrRetry	; vector 24h (0000:0090): critical error	;@1225
	mov word ptr es:[92h], ax	;@122C
	pop es	;@1230
	mov byte ptr Location, 1	; the library's Location = 1: KeyReady does not animate tiles	;@1231
	lea bx, CharGfx	;@1236
	mov cx, 800h	;@123A
	lea dx, FileCharsetUlt	;@123D
	call LoadFile	;@1241
	lea bx, TileGfx	;@1244
	mov cx, 1400h	;@1248
	lea dx, FileShapesUlt	;@124B
	call LoadFile	;@124F
	lea bx, DemoTiles	;@1252
	mov cx, 72h	;@1256
	lea dx, FileDemoUlt	;@1259
	call LoadFile	;@125D
	lea bx, MovesCells	;@1260
	mov cx, 400h	;@1264
	lea dx, FileMovesUlt	;@1267
	call LoadFile	;@126B
	call AskScenarioDisk	; AskScenarioDisk: disabled, returns at once	;@126E
	lea bx, Roster	;@1271
	mov cx, 500h	;@1275
	lea dx, FileRosterUlt	;@1278
	call LoadFile	;@127C
	mov dx, 1CC0h	; bottom line of the frame at text row 23	;@127F
	call DrawMenuFrame	;@1282
	mov dh, 0Ah	;@1285
	mov dl, 0Eh	;@1287
	lea si, MsgUltimaIII	; "Ultima III" in the top line of the frame	;@1289
	call PrintAt	;@128D
	mov ah, 6	; 6 rows ...	;@1290
	mov al, 13h	; ... of 19 tiles	;@1292
	lea bx, DemoTiles	;@1294
	lea bp, TileGfx	;@1298
	mov di, 0DC2h	; screen offset of text row 11, column 1	;@129C
	call DrawTileBlock	;@129F
	lea bx, PartyBuf	;@12A2
	mov cx, 112h	;@12A6
	lea dx, FilePartyUlt	;@12A9
	call LoadFile	;@12AD
	mov byte ptr Location, 1	; (PARTY.ULT overwrote it)	;@12B0
	jmp short TitleLoop_Prompt	;@12B5
;------------------------------------------------------------------------------
; TitleLoop: the title screen: play the MOVES.ULT script on the DEMO.ULT landscape (docs/
; FORMATS.md 7) until a key is pressed, then run the main menu and start again.
; Step: a cell number of 0FFh is a pause of `value` rounds; else the cell becomes value/2
; and, when that is a tile of 8 or more, one round follows; tiles below 8 are set without a
; pause. A round is six times AnimateDemo (animate the tiles, redraw the block).
;------------------------------------------------------------------------------
TitleLoop:	mov dx, 1CC0h	;@12B7
	call DrawMenuFrame	;@12BA
	mov dh, 0Ah	;@12BD
	mov dl, 0Eh	;@12BF
	lea si, MsgUltimaIII	;@12C1
	call PrintAt	;@12C5
TitleLoop_Prompt:	mov dh, 17h	;@12C8
	mov dl, 0Ch	;@12CA
	lea si, MsgPressSpace	; "Press <Space>" in the bottom line of the frame	;@12CC
	call PrintAt	;@12D0
TitleLoop_Step:	inc word ptr DemoStep	; starts at 1FFh, so the first step is 0	;@12D3
	cmp word ptr DemoStep, 200h	;@12D7
	jne TitleLoop_Read	;@12DD
	mov word ptr DemoStep, 0	;@12DF
TitleLoop_Read:	mov si, word ptr DemoStep	;@12E5
	mov bl, byte ptr MovesCells[si]	;@12E9
	mov bh, 0	;@12ED
	mov al, byte ptr MovesValues[si]	;@12EF
	cmp bl, 0FFh	;@12F3
	jne TitleLoop_SetCell	;@12F6
	mov ah, al	; a pause of AL rounds	;@12F8
	jmp short TitleLoop_Round	;@12FA
TitleLoop_SetCell:	shr al, 1	;@12FC
	mov byte ptr DemoTiles[bx], al	;@12FE
	cmp al, 8	;@1302
	jb TitleLoop_Step	;@1304
	mov ah, 1	;@1306
TitleLoop_Round:	call AnimateDemo	;@1308
	call AnimateDemo	;@130B
	call AnimateDemo	;@130E
	call AnimateDemo	;@1311
	call AnimateDemo	;@1314
	call AnimateDemo	;@1317
	dec ah	;@131A
	jne TitleLoop_Round	;@131C
	call KeyReady	;@131E
	je TitleLoop_Step	;@1321
	call ReadKey	;@1323
	call RunMainMenu	;@1326
	jmp TitleLoop	;@1329
;------------------------------------------------------------------------------
; DrawMenuFrame: draw the frame of the menu area in colour 2 (magenta, 2222h):
; top line at text row 10 (columns 1-38), left and right columns 0 and 39 (rows 10-23) and a
; bottom line at screen offset DX (always 1CC0h, row 23). The other possible bottom line
; (1CC0h or 1E00h, row 24) is cleared first. A text cell at row r, column c is at offset
; r*140h + c*2. In: DX. Uses: nothing.
;------------------------------------------------------------------------------
DrawMenuFrame:	push ax	;@132B
	push bx	;@132C
	push cx	;@132D
	mov ax, 0	;@132E
	mov bx, 1E00h	;@1331
	xor bx, 1CC0h	;@1334
	xor bx, dx	; BX = 1E00h if DX = 1CC0h, else 1CC0h	;@1338
	mov cx, 28h	; 40 cells	;@133A
DrawMenuFrame_Erase:	call FillCell	;@133D
	add bx, 2	;@1340
	loop DrawMenuFrame_Erase	;@1343
	mov ax, 2222h	; pixels 0 2 0 2 ...: a dotted magenta line	;@1345
	mov bx, dx	;@1348
	mov cx, 28h	;@134A
DrawMenuFrame_Bottom:	call FillCell	;@134D
	add bx, 2	;@1350
	loop DrawMenuFrame_Bottom	;@1353
	mov bx, 0C82h	; row 10, column 1	;@1355
	mov cx, 26h	;@1358
DrawMenuFrame_Top:	call FillCell	;@135B
	add bx, 2	;@135E
	loop DrawMenuFrame_Top	;@1361
	mov bx, 0C80h	; row 10, column 0	;@1363
	mov cx, 0Eh	;@1366
DrawMenuFrame_Left:	call FillCell	;@1369
	add bx, 140h	; next text row	;@136C
	loop DrawMenuFrame_Left	;@1370
	mov bx, 0CCEh	; row 10, column 39	;@1372
	mov cx, 0Eh	;@1375
DrawMenuFrame_Right:	call FillCell	;@1378
	add bx, 140h	;@137B
	loop DrawMenuFrame_Right	;@137F
	pop cx	;@1381
	pop bx	;@1382
	pop ax	;@1383
	ret	;@1384
;------------------------------------------------------------------------------
; ClearMenu: clear the inside of the frame, text rows 11-22, columns 1-38 (where the
; DEMO.ULT landscape is drawn), with the BIOS scroll function. Uses: nothing.
;------------------------------------------------------------------------------
ClearMenu:	push ax	;@1385
	push bx	;@1386
	push cx	;@1387
	push dx	;@1388
	push bp	;@1389
	mov al, 0	; 0 lines: clear the window	;@138A
	mov ch, 0Bh	;@138C
	mov cl, 1	;@138E
	mov dh, 16h	;@1390
	mov dl, 26h	;@1392
	mov bh, 0	; fill attribute 0	;@1394
	mov ah, 6	; BIOS 10h/06h: scroll up window CH,CL - DH,DL	;@1396
	int 10h	;@1398
	pop bp	;@139A
	pop dx	;@139B
	pop cx	;@139C
	pop bx	;@139D
	pop ax	;@139E
	ret	;@139F
;------------------------------------------------------------------------------
; RunMainMenu: the main menu ("From the depths of hell...", Option: Return to the View,
; Organize a Party, Journey Onward). The choice is made with AskChoice (choose a key of a list,
; show its name, confirm with Enter). J: JourneyOnward (returns only on an error);
; O: the party menu; R or Esc: back to the title. Uses: AX.
;------------------------------------------------------------------------------
RunMainMenu:	pushf	;@13A0
	push bx	;@13A1
	push cx	;@13A2
	push dx	;@13A3
	push si	;@13A4
	push di	;@13A5
RunMainMenu_Redraw:	call ClearMenu	;@13A6
	mov dx, 1CC0h	;@13A9
	call DrawMenuFrame	;@13AC
	mov dh, 15h	;@13AF
	mov dl, 3	;@13B1
	lea si, MsgCopyright	;@13B3
	call PrintAt	;@13B7
	mov dh, 16h	;@13BA
	mov dl, 0Dh	;@13BC
	lea si, MsgLordBritish	;@13BE
	call PrintAt	;@13C2
	mov dh, 0Bh	;@13C5
	mov dl, 7	;@13C7
	lea si, MsgFromDepths	;@13C9
	call PrintAt	;@13CD
	mov dh, 0Ch	;@13D0
	mov dl, 7	;@13D2
	lea si, MsgVengeance	;@13D4
	call PrintAt	;@13D8
	mov dh, 0Fh	;@13DB
	mov dl, 10h	;@13DD
	lea si, MsgOptionSpace	;@13DF
	call PrintAt	;@13E3
	mov dh, 11h	;@13E6
	mov dl, 0Bh	;@13E8
	lea si, MsgMenuReturn	;@13EA
	call PrintAt	;@13EE
	mov dh, 12h	;@13F1
	mov dl, 0Ch	;@13F3
	lea si, MsgMenuOrganize	;@13F5
	call PrintAt	;@13F9
	mov dh, 13h	;@13FC
	mov dl, 0Dh	;@13FE
	lea si, MsgMenuJourney	;@1400
	call PrintAt	;@1404
	mov dh, 0Fh	;@1407
	mov dl, 17h	;@1409
	call SwapCursor	;@140B
	mov cx, 4	; 4 keys: R O J Esc	;@140E
	lea di, MainMenuKeys	;@1411
	lea si, MainMenu	;@1415
	call AskChoice	;@1419
	cmp al, 4Ah	; 'J'	;@141C
	je RunMainMenu_Journey	;@141E
	cmp al, 4Fh	; 'O'	;@1420
	je RunMainMenu_Organize	;@1422
	pop di	;@1424
	pop si	;@1425
	pop dx	;@1426
	pop cx	;@1427
	pop bx	;@1428
	popf	;@1429
	ret	;@142A
RunMainMenu_Journey:	call JourneyOnward	;@142B
	jmp RunMainMenu_Redraw	;@142E
RunMainMenu_Organize:	call RunOrganizeMenu	;@1431
	jmp RunMainMenu_Redraw	;@1434
;------------------------------------------------------------------------------
; JourneyOnward: start the game. Refuses with "(No Party)" when no party is formed,
; "(Strange Disk)" when DiskCheckResult is 0FFh (never: see AskScenarioDisk) and "(No Active
; Players)" when none of the four party records is Good or Poisoned. Otherwise chain-loads
; EXODUS.BIN (docs/HANDOFF.md): open it with the PSP's FCB, record size = file size, plant
; at PSP:00FA "int 21h" (CD 21) followed by "jmp word ptr [1328h]" (FF 26 28 13) and jump
; there with AH = 14h and SP = 00FA: DOS reads the whole file to 0100, over this program,
; and the jmp goes through EXODUS's entry vector at 1328. The open is not checked.
;------------------------------------------------------------------------------
JourneyOnward:	cmp byte ptr PartySize, 0	; party size	;@1437
	je JourneyOnward_NoParty	;@143C
	cmp byte ptr DiskCheckResult, 0FFh	;@143E
	je JourneyOnward_Strange	;@1443
	call AnyAlive	;@1445
	cmp ah, 0	;@1448
	je JourneyOnward_NoActive	;@144B
	mov dx, 100h	;@144D
	mov ah, 1Ah	; DOS 1Ah: DTA = 0100	;@1450
	int 21h	;@1452
	lea si, FileExodusBin	; "EXODUS.BIN"	;@1454
	lea di, PspFcb	;@1458
	mov al, 0	;@145C
	mov ah, 29h	; DOS 29h: parse the file name into the FCB at PSP:005C	;@145E
	int 21h	;@1460
	mov dx, di	;@1462
	mov ah, 0Fh	; DOS 0Fh: open the FCB	;@1464
	int 21h	;@1466
	mov ax, word ptr FcbFileSize	; file size ...	;@1468
	mov word ptr FcbRecSize, ax	; ... as the record size	;@146B
	mov word ptr ChainInt21, 21CDh	; CD 21: int 21h	;@146E
	mov word ptr ChainJmp, 26FFh	; FF 26: jmp word ptr [...]	;@1474
	mov word ptr ChainJmpAddr, 1328h	; ... [1328h]: EXODUS's entry vector	;@147A
	mov word ptr FcbCurBlock, 0	;@1480
	mov byte ptr FcbCurRec, 0	;@1486
	mov ah, 14h	; DOS 14h: sequential read, done by the planted int 21h	;@148B
	lea sp, ChainInt21	;@148D
	jmp sp	;@1491
JourneyOnward_NoParty:	call ClearMenu	;@1493
	mov dh, 15h	;@1496
	mov dl, 0Fh	;@1498
	lea si, MsgNoParty	;@149A
	call PrintAt	;@149E
	call WaitSpace	;@14A1
	ret	;@14A4
JourneyOnward_Strange:	call ClearMenu	;@14A5
	mov dh, 15h	;@14A8
	mov dl, 0Bh	;@14AA
	lea si, MsgStrangeDisk	;@14AC
	call PrintAt	;@14B0
	call WaitSpace	;@14B3
	ret	;@14B6
JourneyOnward_NoActive:	call ClearMenu	;@14B7
	mov dh, 15h	;@14BA
	mov dl, 9	;@14BC
	lea si, MsgNoActivePlayers	;@14BE
	call PrintAt	;@14C2
	call WaitSpace	;@14C5
	ret	;@14C8
CODE ENDS
END
